import{b as o,O as r,g as d,j as e}from"./chunks/framework.DcaUmd3X.js";const p=JSON.parse('{"title":"缺陷管理：Bug 的一生","description":"","frontmatter":{},"headers":[],"relativePath":"testing/execution/bug-management/index.md","filePath":"测试理论与实践/2.测试执行过程/05.缺陷管理.md","lastUpdated":1781688244000}'),a={name:"testing/execution/bug-management/index.md"};function n(g,t,s,u,l,i){return r(),d("div",null,[...t[0]||(t[0]=[e(`<h1 id="缺陷管理-bug-的一生" tabindex="-1">缺陷管理：Bug 的一生 <a class="header-anchor" href="#缺陷管理-bug-的一生" aria-label="Permalink to &quot;缺陷管理：Bug 的一生&quot;">​</a></h1><blockquote><p>Bug 从被发现到被关闭，不是&quot;记一下就行&quot;——写清楚、分对级、跟到底，每一步都直接影响修复效率。</p></blockquote><h2 id="一个好-bug-报告的九要素" tabindex="-1">一个好 Bug 报告的九要素 <a class="header-anchor" href="#一个好-bug-报告的九要素" aria-label="Permalink to &quot;一个好 Bug 报告的九要素&quot;">​</a></h2><p>Bug 报告是测试人员和开发人员之间最重要的沟通媒介。一条完整的缺陷记录包含 9 个核心要素（详见<a href="/testing/appendix/bug-record.html">附录：缺陷记录</a>）：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th>要素</th><th>回答的问题</th><th>一句话说明</th><th>坏例子</th><th>好例子</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>缺陷编号</strong></td><td>这是哪个 Bug？</td><td>唯一标识，全流程追溯</td><td>—</td><td>BUG-20240615-001</td></tr><tr><td style="text-align:center;">2</td><td><strong>缺陷标题</strong></td><td>一句话说清什么问题？</td><td>模块 + 条件 + 现象</td><td>&quot;登录有问题&quot;</td><td>&quot;登录页：正确账号密码点击登录后页面白屏&quot;</td></tr><tr><td style="text-align:center;">3</td><td><strong>严重程度</strong></td><td>影响有多大？</td><td>测试人员根据对系统的影响判定</td><td>不填</td><td>Critical / High / Medium / Low</td></tr><tr><td style="text-align:center;">4</td><td><strong>优先级</strong></td><td>多快必须修？</td><td>产品/项目经理根据业务紧急度判定</td><td>不填</td><td>P0 / P1 / P2 / P3</td></tr><tr><td style="text-align:center;">5</td><td><strong>重现步骤</strong></td><td>怎么复现？</td><td>别人照着做一定看到同样现象</td><td>&quot;多试几次就能看到&quot;</td><td>&quot;1.打开登录页 2.输入 <a href="mailto:test@xx.com" target="_blank" rel="noreferrer">test@xx.com</a> 3.输入密码 4.点击登录 5.页面白屏&quot;</td></tr><tr><td style="text-align:center;">6</td><td><strong>环境信息</strong></td><td>在什么环境上发现的？</td><td>OS、浏览器、版本</td><td>&quot;Windows&quot;</td><td>&quot;Windows 11 23H2 / Chrome 125.0 / 1920×1080&quot;</td></tr><tr><td style="text-align:center;">7</td><td><strong>期望 vs 实际</strong></td><td>期望怎样 vs 实际怎样？</td><td>不写期望的 Bug 报告是半成品</td><td>&quot;它坏了&quot;</td><td>期望：跳转首页 / 实际：页面白屏</td></tr><tr><td style="text-align:center;">8</td><td><strong>附件</strong></td><td>有什么证据？</td><td>截图、录屏、日志、接口响应</td><td>没有截图</td><td>附白屏截图 + Console 报错日志</td></tr><tr><td style="text-align:center;">9</td><td><strong>备注</strong></td><td>有什么要补充的？</td><td>发现频率、临时绕过方案、关联 Bug</td><td>—</td><td>&quot;100% 必现，清理缓存后仍可复现&quot;</td></tr></tbody></table><blockquote><p>9 个要素中，<strong>重现步骤</strong>是最关键的——别人照着做能复现，Bug 就已经解决了一半。<strong>严重程度 ≠ 优先级</strong>——严重性是技术影响（测试定），优先级是业务紧急度（产品定）。完整填写指南见<a href="/testing/appendix/bug-record.html">附录：缺陷记录</a>。</p></blockquote><h3 id="写好-bug-报告的核心口诀-clear" tabindex="-1">写好 Bug 报告的核心口诀：CLEAR <a class="header-anchor" href="#写好-bug-报告的核心口诀-clear" aria-label="Permalink to &quot;写好 Bug 报告的核心口诀：CLEAR&quot;">​</a></h3><ul><li><strong>C</strong>an reproduce（能复现）：别人照着你的步骤，一定能看到同样的现象</li><li><strong>L</strong>imited to one issue（只描述一个问题）：不要在一个 Bug 报告里塞三个问题，开发和测试都没法跟踪</li><li><strong>E</strong>xpected vs actual（期望 vs 实际）：只说&quot;有问题&quot;是废话，说清&quot;期望怎样，实际怎样&quot;</li><li><strong>A</strong>ccurate environment（环境准确）：同一个 Bug 在 Chrome 上有、在 Safari 上没有，你不说环境，开发在 Safari 上试了半天说&quot;我这没问题啊&quot;</li><li><strong>R</strong>elevant evidence（有证据）：截图、录屏、日志、接口响应，越多越好</li></ul><h2 id="bug-的一生-五个状态" tabindex="-1">Bug 的一生：五个状态 <a class="header-anchor" href="#bug-的一生-五个状态" aria-label="Permalink to &quot;Bug 的一生：五个状态&quot;">​</a></h2><p>一个 Bug 从被发现到寿终正寝，通常经历五个阶段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>报告 Bug ──→ 审核确认 ──→ 开发修复 ──→ 测试验证 ──→ 关闭</span></span>
<span class="line"><span>(发现)     (是不是bug)   (改代码)    (改好了吗)    (完了)</span></span></code></pre></div><h3 id="_1-报告-bug" tabindex="-1">1. 报告 Bug <a class="header-anchor" href="#_1-报告-bug" aria-label="Permalink to &quot;1. 报告 Bug&quot;">​</a></h3><p>测试人员或用户发现并提交。这时候 Bug 状态是 <strong>New（新建）</strong>。</p><p><strong>谁来做</strong>：发现者。不需要判断&quot;是不是真的 bug&quot;——先记下来，审核阶段再判断。</p><h3 id="_2-审核确认" tabindex="-1">2. 审核确认 <a class="header-anchor" href="#_2-审核确认" aria-label="Permalink to &quot;2. 审核确认&quot;">​</a></h3><p>项目经理或开发负责人判断这个 Bug：</p><ul><li><strong>有效且该修</strong> → 确认，分配优先级，指派开发，状态变为 <strong>Open（打开）</strong></li><li><strong>重复</strong> → 标记为 Duplicate，关联到已有的 Bug</li><li><strong>不是 Bug / 设计如此</strong> → 标记为 By Design，说明原因后关闭</li><li><strong>信息不足无法复现</strong> → 标记为 Need More Info，打回给报告者补充</li></ul><p><strong>关键</strong>：这个环节是 Bug 的筛子——不是所有提交的 Bug 都要修，但每一个都需要有明确的处置结论。</p><h3 id="敏捷中的-bug-分类会议-bug-triage" tabindex="-1">敏捷中的 Bug 分类会议（Bug Triage） <a class="header-anchor" href="#敏捷中的-bug-分类会议-bug-triage" aria-label="Permalink to &quot;敏捷中的 Bug 分类会议（Bug Triage）&quot;">​</a></h3><p>在敏捷团队中，Bug 分类不应该是负责人一个人拍板，而是<strong>团队共同决策</strong>。</p><p>实践中很多敏捷团队每个迭代开一次 15 分钟的 <strong>Bug Council</strong>（Bug 分类会）——测试、开发、产品三方一起过一遍新提交的 Bug：</p><ul><li>测试说清楚这个 Bug 的影响</li><li>开发评估修复成本和风险</li><li>产品根据业务优先级拍板：这轮修、下轮修、还是不修</li></ul><blockquote><p>单人审核容易出两件事：要么负责人把 Bug 压着不修（开发抵触），要么负责人让所有 Bug 都修（测试满意但进度炸了）。三方一起决策，权责透明，没人能甩锅。</p></blockquote><h3 id="_3-开发修复" tabindex="-1">3. 开发修复 <a class="header-anchor" href="#_3-开发修复" aria-label="Permalink to &quot;3. 开发修复&quot;">​</a></h3><p>开发人员接手，定位原因、修改代码。状态变为 <strong>In Progress（修复中）</strong>。</p><p>修完后提交代码，Bug 状态变为 <strong>Fixed / Resolved（已修复）</strong>，等待验证。</p><h3 id="_4-测试验证" tabindex="-1">4. 测试验证 <a class="header-anchor" href="#_4-测试验证" aria-label="Permalink to &quot;4. 测试验证&quot;">​</a></h3><p>测试人员在修复后的版本上重新验证：</p><ul><li><strong>修好了</strong> → 状态变为 <strong>Verified（已验证）</strong></li><li><strong>没修好 / 修出了新问题</strong> → 状态打回 <strong>Reopened（重新打开）</strong>，附上复现信息</li></ul><blockquote><p>验证时不要只测&quot;这个 Bug 描述的场景&quot;。想想这个修复可能影响了什么别的功能——顺手做一轮小范围回归。</p></blockquote><h3 id="_5-关闭" tabindex="-1">5. 关闭 <a class="header-anchor" href="#_5-关闭" aria-label="Permalink to &quot;5. 关闭&quot;">​</a></h3><p>验证通过、产品上线后，状态变为 <strong>Closed（已关闭）</strong>。</p><h3 id="bug-度量-用数据看质量趋势" tabindex="-1">Bug 度量：用数据看质量趋势 <a class="header-anchor" href="#bug-度量-用数据看质量趋势" aria-label="Permalink to &quot;Bug 度量：用数据看质量趋势&quot;">​</a></h3><p>以上是单个 Bug 的生命周期。但还有另一个更重要的视角：<strong>不要只看一个 Bug 的生死，要看一群 Bug 的趋势。</strong></p><p>几个关键指标：</p><table tabindex="0"><thead><tr><th>指标</th><th>怎么算</th><th>异常信号</th></tr></thead><tbody><tr><td><strong>Bug 发现率</strong></td><td>每周新增 Bug 数</td><td>突然飙升——是否最近的代码质量下降了？</td></tr><tr><td><strong>Bug 修复率</strong></td><td>每周关闭 Bug 数</td><td>修复率 &lt; 发现率——Bug 债务在积累</td></tr><tr><td><strong>重开率</strong></td><td>Reopened 数 / 已修复数</td><td>&gt; 10% —— 开发没找准根因，或者在修 A 的时候搞坏了 B</td></tr><tr><td><strong>平均修复时间</strong></td><td>从 Open 到 Fixed 的时长</td><td>持续增长——团队可能超负荷，或者代码复杂度在上升</td></tr></tbody></table><blockquote><p>这些指标不是用来考核个人的，是用来<strong>看质量趋势</strong>的。Bug 发现率下降了不一定是好事——可能是测得少了，也可能是质量真的提升了。结合其他指标一起看才有意义。</p></blockquote><h3 id="探索式测试中的-bug-报告" tabindex="-1">探索式测试中的 Bug 报告 <a class="header-anchor" href="#探索式测试中的-bug-报告" aria-label="Permalink to &quot;探索式测试中的 Bug 报告&quot;">​</a></h3><p>目前 Bug 的五个阶段看起来是一个独立工作流，但在基于会话的测试管理（SBTM）实践中，Bug 报告是<strong>整合进测试会话</strong>的。</p><p>一个探索式测试会话结束时，产出物不是&quot;一个 Bug 报告&quot;，而是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>会话输出 = 测试笔记 + 发现的问题清单 + Bug 报告（如适用）+ 环境/数据记录</span></span></code></pre></div><p>Bug 报告不是测完之后&quot;另起炉灶&quot;写的，而是探索过程中自然产出的。这个心态转变很重要——<strong>Bug 报告不是测试的&quot;成果&quot;，而是测试的&quot;记录&quot;。</strong></p><h2 id="优先级-vs-严重性-不是一回事" tabindex="-1">优先级 vs 严重性：不是一回事 <a class="header-anchor" href="#优先级-vs-严重性-不是一回事" aria-label="Permalink to &quot;优先级 vs 严重性：不是一回事&quot;">​</a></h2><p>这是初学者最容易搞混的概念：</p><table tabindex="0"><thead><tr><th>维度</th><th>问什么问题</th><th>谁决定</th></tr></thead><tbody><tr><td><strong>严重性（Severity）</strong></td><td>这个 Bug 对系统的影响有多大？</td><td>测试人员</td></tr><tr><td><strong>优先级（Priority）</strong></td><td>这个 Bug 应该多快修？</td><td>产品经理 / 项目经理</td></tr></tbody></table><p><strong>严重性高不一定优先级高。</strong> 举个极端例子：</p><ul><li>一个 Bug 导致所有用户数据丢失 —— 严重性 Critical，优先级也是最高</li><li>但一个 Bug 导致后台管理页面某个报表错了一行 —— 严重性可能只是 Low，但如果老板明天要给投资人看这份报表，优先级就是 High</li></ul><p>反过来也成立：一个首页 Logo 歪了 2px，严重性 Low，但如果明天是公司品牌发布会，优先级可能瞬间飙升。</p><h3 id="严重性四级" tabindex="-1">严重性四级 <a class="header-anchor" href="#严重性四级" aria-label="Permalink to &quot;严重性四级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>标签</th><th>标准</th><th>例子</th></tr></thead><tbody><tr><td><strong>紧急</strong></td><td>Critical</td><td>系统崩溃、数据丢失、核心功能完全不可用</td><td>支付接口挂了，用户无法付款</td></tr><tr><td><strong>高级</strong></td><td>High</td><td>核心功能严重受损，但有临时绕过方案</td><td>某个支付方式不可用，但用户可切换到其他方式</td></tr><tr><td><strong>中级</strong></td><td>Medium</td><td>功能部分异常，不影响核心流程</td><td>订单详情页的优惠金额显示错误</td></tr><tr><td><strong>低级</strong></td><td>Low</td><td>轻微瑕疵，不影响使用</td><td>按钮颜色偏了 1px、一个错别字</td></tr></tbody></table><h3 id="优先级四级" tabindex="-1">优先级四级 <a class="header-anchor" href="#优先级四级" aria-label="Permalink to &quot;优先级四级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>含义</th><th>什么时候修</th></tr></thead><tbody><tr><td><strong>P0 - 紧急</strong></td><td>阻塞上线，必须立即修复</td><td>现在、马上、不能等</td></tr><tr><td><strong>P1 - 高</strong></td><td>当前版本必须修</td><td>本次迭代内</td></tr><tr><td><strong>P2 - 中</strong></td><td>应该修，但不阻塞上线</td><td>下次迭代</td></tr><tr><td><strong>P3 - 低</strong></td><td>锦上添花</td><td>有空再说</td></tr></tbody></table><h2 id="bug-的集群效应" tabindex="-1">Bug 的集群效应 <a class="header-anchor" href="#bug-的集群效应" aria-label="Permalink to &quot;Bug 的集群效应&quot;">​</a></h2><p><a href="/testing/basics/what-is-testing.html">重新认识软件测试</a>中有一条原则：<strong>Bug 不是均匀分布的。</strong></p><blockquote><p>一个模块发现 3 个 bug，它后面可能还藏着 10 个。</p></blockquote><p>实践中这意味着：</p><ul><li>某个模块 Bug 集中爆发 → 不是测试人员针对它，而是<strong>它本身质量就差</strong>，需要重点关注</li><li>被频繁 Reopened 的 Bug → 说明开发没找准根因，或者模块耦合度太高，改一处坏一片</li><li>多做一轮&quot;Bug 聚类分析&quot;：把 Bug 按模块、按类型、按根因分类，往往能找到系统性问题</li></ul><p>有一个值得参考的做法：<strong>测试团队定期做 Bug 回顾</strong>，不是追责，而是找规律——哪类 Bug 最常出现？哪个开发写的代码 Bug 最少？（然后请他来分享经验）</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>缺陷记录九要素中，<strong>重现步骤</strong>是最关键的——别人照做能复现，Bug 就已经解决了一半</li><li>写好 Bug 的口诀 CLEAR：能复现、只描述一个问题、说清期望 vs 实际、写对环境、附上证据</li><li>Bug 生命周期五阶段：报告 → 审核 → 修复 → 验证 → 关闭。在敏捷团队中，审核阶段推荐用 <strong>Bug Council</strong> 三方共同决策，而非单人拍板</li><li><strong>严重性 ≠ 优先级</strong>：严重性说的是&quot;影响多大&quot;（测试定），优先级说的是&quot;多快该修&quot;（产品定）</li><li>Bug 有集群效应——发现问题多的模块值得投入更多测试资源，Bug 回顾能找到系统性根因</li><li><strong>用度量看趋势</strong>：Bug 发现率、修复率、重开率、平均修复时间——四个指标组合看，别只看单个数字</li><li>探索式测试中 Bug 报告是会话的自然产出，不是测完另起炉灶写的</li></ol>`,60)])])}const b=o(a,[["render",n]]);export{p as __pageData,b as default};
